async (cursor, num, params) => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const pageStart = Date.now();
  const turns = () => [...document.querySelectorAll('[data-turn-key], [data-message-author-role]')].filter(e => e.getClientRects().length);   // 只算看得见的：点「新聊天」后首页 DOM 里会留一个隐藏的旧对话节点
  const asst = () => [...document.querySelectorAll('[data-message-author-role="assistant"]')];
  const busy = () => !!document.querySelector('[data-testid="stop-button"], form button[aria-label*="停止"], form button[aria-label*="Stop"]');
  const INPUT = '#prompt-textarea, form .ProseMirror[contenteditable="true"]';
  // 只认看得见的：点「新聊天」后上一条对话的整块表单被缓存成隐藏节点留在 DOM 里，querySelector 先拿到的是它（2026-10-17 两次把 prompt 粘进隐藏的旧输入框，发送按钮自然不亮）
  const shown = sel => [...document.querySelectorAll(sel)].find(e => e.getClientRects().length) || null;
  const sendBtn = () => shown('[data-testid="send-button"], form button[aria-label="发送"], form button[aria-label="Send prompt"], form button[aria-label="Send"]');
  const creating = () => !!document.evaluate('//*[contains(text(),"正在创建图片") or contains(text(),"Creating image") or contains(text(),"正在生成图片") or contains(text(),"Generating image")]', document, null, 9, null).singleNodeValue;
  const genImgs = () => [...document.querySelectorAll('[data-testid="generated-image-gallery"] img, main img')].filter(i => (i.closest('[data-testid="generated-image-gallery"]') || /已生成图像|Generated image/.test(i.alt || '') || /backend-api\/estuary\/content|oaiusercontent\.com/.test(i.currentSrc || i.src)) && !i.closest('[data-message-author-role="user"]') && i.complete && i.naturalWidth >= 256 && i.getClientRects().length && !(window.__cgiBefore && window.__cgiBefore.has(i.currentSrc || i.src)));   // 只认看得见的、发送前不在的：缓存成隐藏节点的旧对话里的图不算（2026-10-17 曾把上一张仓鼠当成这一轮的取回来）
  const turnDone = i => { const t = i.closest('[data-talvt-turn-state]'); return t ? t.getAttribute('data-talvt-turn-state') === 'complete' : null; };
  // 风控页：整页「无法加载你的账户 / 浏览器检查未能完成」，或回复位置的 cloudflare_challenge。要人在这个常驻标签上点「重新加载」/ 过验证
  const blockedPage = () => /浏览器检查未能完成|无法加载你的账户|Verify you are human|browser check|cloudflare_challenge/i.test((document.body && document.body.innerText) || '');
  if (blockedPage()) throw new Error('[chatgpt-image] ChatGPT 风控页（浏览器检查 / Cloudflare）：在 ChatGPT 标签上点「重新加载」/ 过验证 —— ' + ((document.body.innerText || '').trim().split('\n').slice(0, 3).join(' / ').slice(0, 120)));
  if (!cursor) {
    let pm = null;
    for (let i = 0; i < 30 && !(pm = shown(INPUT)); i++) await sleep(300);
    if (!pm) throw new Error('[chatgpt-image] 没找到输入框 url=' + location.pathname + location.search);
    // 常驻标签：上一轮停在 /c/<id>。点侧栏「新聊天」开新对话（页内跳转，不整页重载——每轮重载像脚本，2026-10-17 撞过风控）
    if (turns().length || /^\/c\//.test(location.pathname)) {
      const leaf = t => [...document.querySelectorAll('a,button,div,span')].find(e => e.childElementCount === 0 && e.textContent.trim() === t);
      const btn = document.querySelector('[data-testid="create-new-chat-button"]') || leaf('新聊天') || leaf('New chat');
      if (btn) (btn.closest('a,button') || btn).click();
      else location.assign('/');   // 找不到按钮才整页回首页（少见，下一轮又能点按钮了）
      const t1 = Date.now();
      while (Date.now() - t1 < 8000 && (turns().length || /^\/c\//.test(location.pathname) || !shown(INPUT))) await sleep(300);
      if (turns().length) throw new Error('[chatgpt-image] 点了「新聊天」，页面上还是上一条对话 url=' + location.pathname);
      pm = shown(INPUT);
      if (!pm) throw new Error('[chatgpt-image] 开了新对话却没找到输入框');
    }
    const text = '请直接用图像生成工具画一张方形（1:1）的图，不要提问、不要解释，只出图：\n' + params.prompt;
    const dt = new DataTransfer();
    dt.setData('text/plain', text);
    const paste = el => { el.focus(); el.dispatchEvent(new ClipboardEvent('paste', { clipboardData: dt, bubbles: true, cancelable: true })); };
    paste(pm);
    let send = null;
    const t0 = Date.now();
    let repasted = false;
    while (Date.now() - t0 < 15000) {
      send = sendBtn();
      if (send && !send.disabled) break;
      // 新对话刚切过去时输入框会被 React 换掉一次：字粘进了旧的那个、发送按钮不亮（2026-10-17 16:07）。6s 还不亮就重新找输入框、清空再粘一次
      if (!repasted && Date.now() - t0 > 6000) { repasted = true; pm = shown(INPUT) || pm; pm.focus(); document.execCommand('selectAll'); document.execCommand('delete'); paste(pm); }
      await sleep(300);
    }
    if (!send || send.disabled) throw new Error('[chatgpt-image] 粘贴后 15s 发送按钮仍不可用（输入框字数 ' + pm.textContent.length + '）');
    const sent = () => turns().length > 0 || busy() || /^\/c\//.test(location.pathname);
    const tries = [
      ['click', () => send.click()],
      ['requestSubmit', () => { const f = send.closest('form'); if (f) f.requestSubmit(send); }],
      ['enter', () => pm.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true, cancelable: true }))],
    ];
    window.__cgiBefore = null; window.__cgiBefore = new Set(genImgs().map(i => i.currentSrc || i.src));
    const used = [];
    for (const [name, fire] of tries) {
      used.push(name);
      fire();
      for (let i = 0; i < 10 && !sent(); i++) await sleep(300);
      if (sent()) break;
    }
    if (!sent()) throw new Error('[chatgpt-image] 试过 ' + used.join(' / ') + ' 都没把消息发出去');
    window.__cgiT0 = Date.now();
    window.__cgiSrc = null; window.__cgiSince = 0; window.__cgiTxt = null; window.__cgiTxtSince = 0;
  }
  const deadline = Math.min(Date.now() + 22000, pageStart + 26000);
  const challenged = () => /cloudflare_challenge/.test((document.querySelector('main') || document.body).innerText || '');
  while (Date.now() < deadline) {
    // ChatGPT 风控：回复位置出现「cloudflare_challenge / 重试」，消息根本没到服务端（对话 id 还是 local-…）。马上抛，别干等 190s
    if (challenged() || blockedPage()) throw new Error('[chatgpt-image] ChatGPT 弹了 Cloudflare 校验 / 浏览器检查——发得太勤，歇一阵；要人在 ChatGPT 标签上点「重试」「重新加载」/ 过验证');
    const imgs = genImgs();
    const img = imgs.at(-1);
    const done = img ? turnDone(img) : null;
    const working = done === null ? (busy() || creating()) : !done;
    if (img && !working) {
      const src = img.currentSrc || img.src;
      if (src !== window.__cgiSrc) { window.__cgiSrc = src; window.__cgiSince = Date.now(); }
      else if (Date.now() - window.__cgiSince > 3000) {
        const r = await fetch(src, { credentials: 'include' });
        if (!r.ok) throw new Error('[chatgpt-image] 取图 HTTP ' + r.status);
        const bmp = await createImageBitmap(await r.blob());
        const k = Math.min(1, 1024 / Math.max(bmp.width, bmp.height));
        const c = document.createElement('canvas');
        c.width = Math.round(bmp.width * k); c.height = Math.round(bmp.height * k);
        c.getContext('2d').drawImage(bmp, 0, 0, c.width, c.height);
        const png = c.toDataURL('image/png').split(',')[1];
        const m = src.match(/id=([^&]+)/);
        return { items: [{ guid: m ? m[1] : ('cg' + Date.now()), png, index: '0' }], cursor: '' };
      }
    } else if (!img && !working) {
      // 只回了文字（拒绝 / 反问）：只看 ChatGPT 自己那一轮——跳过含我们提示词的那轮（2026-10-17 误把自己发的消息当成回复、生图途中判了失败），
      // 那一轮要标着完成、文字 8s 不变、离发送已过 45s，才算
      const head = String(params.prompt).slice(0, 24);
      const a = asst().at(-1) || [...document.querySelectorAll('[data-talvt-turn-state]')].filter(t => !(t.innerText || '').includes(head)).at(-1);
      const st = a ? (a.closest('[data-talvt-turn-state]') || a).getAttribute('data-talvt-turn-state') : null;
      const txt = a ? (a.innerText || '').trim() : '';
      if (txt && !txt.includes(head) && st !== 'streaming' && st !== 'pending' && st !== 'in_progress') {
        if (txt === window.__cgiTxt) {
          if (Date.now() - window.__cgiTxtSince > 8000 && Date.now() - window.__cgiT0 > 45000 && (st === null || st === 'complete')) throw new Error('[chatgpt-image] ChatGPT 只回了文字、没出图：' + txt.slice(0, 200));
        } else { window.__cgiTxt = txt; window.__cgiTxtSince = Date.now(); }
      }
    }
    await sleep(500);
  }
  const elapsed = Date.now() - (window.__cgiT0 || pageStart);
  if (elapsed > 190000) throw new Error('[chatgpt-image] 190s 内没等到图');
  return { items: [], pending: true, cursor: String(Number(cursor || 0) + 1) };
}
